import{_ as e,o,c as t,ae as i}from"./chunks/framework.Co1PSFSm.js";const m=JSON.parse('{"title":"Guías de Backup Total y Parcial","description":"","frontmatter":{},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md"}'),r={name:"guides/index.md"};function n(c,a,s,l,d,p){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="guias-de-backup-total-y-parcial" tabindex="-1">Guías de Backup Total y Parcial <a class="header-anchor" href="#guias-de-backup-total-y-parcial" aria-label="Permalink to &quot;Guías de Backup Total y Parcial&quot;">​</a></h1><p>El panel de configuración permite personalizar exactamente qué carpetas e información quieres enviar a tu almacenamiento (Wasabi S3).</p><h2 id="backup-total-proteccion-total-inteligente" tabindex="-1">Backup Total (Protección Total Inteligente) <a class="header-anchor" href="#backup-total-proteccion-total-inteligente" aria-label="Permalink to &quot;Backup Total (Protección Total Inteligente)&quot;">​</a></h2><p>Para usuarios que no quieren complicaciones (o plan Enterprise autoconfigurado): En el panel verás el tag <code>[ALL_SYSTEM_ROOT]</code>. El sistema seleccionará dinámicamente todo el disco principal del servidor, excluyendo automáticamente archivos temporales (<code>/proc</code>, <code>/sys</code>, <code>/tmp</code>).</p><ul><li>Para ejecutarlo de inmediato: Haz click en el botón <strong>Full</strong>.</li></ul><h2 id="backup-parcial-carpetas-especificas" tabindex="-1">Backup Parcial (Carpetas Específicas) <a class="header-anchor" href="#backup-parcial-carpetas-especificas" aria-label="Permalink to &quot;Backup Parcial (Carpetas Específicas)&quot;">​</a></h2><p>Si necesitas hacer backup solo de partes concretas:</p><ol><li>Abre el <strong>FileExplorer</strong> en tu panel.</li><li>Expande el árbol de directorios de tu servidor o contenedores.</li><li>Selecciona las rutas necesarias (por ejemplo, <code>/var/www/html</code> o <code>/var/lib/mysql</code>).</li><li>Haz clic en <strong>Save Configuration</strong> o <strong>Lock Selection</strong>.</li><li>Si deseas ejecutarlo manualmente ahora, presiona <strong>Force Selected</strong>.</li></ol><h2 id="snapshot-modes" tabindex="-1">Snapshot Modes <a class="header-anchor" href="#snapshot-modes" aria-label="Permalink to &quot;Snapshot Modes&quot;">​</a></h2><p>Existen dos estrategias de backup para garantizar consistencia:</p><ul><li><strong>LIVE (Default):</strong> El backup corre sin pausar ningún servicio. Útil para cero downtime, aunque podría generar una ligera inconsistencia en bases de datos muy activas si no hay volcado SQL programado.</li><li><strong>CONSISTENT (Enterprise):</strong> Realiza una micropausa controlada (por ejemplo <code>docker pause</code>) durante la toma del snapshot de la base de datos, asegurando una copia 100% exacta y consistente, a cambio de unos segundos de downtime.</li></ul>',11)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
